INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Datenschutzgesetze > National (BDSG)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Regelt das Bundesdatenschutzgesetz (BDSG) den Umgang mit personenbezogenen Daten in Deutschland?', 2, '[{"text": "Ja", "correct": true, "because": "Das BDSG ergänzt die DSGVO für nationale Regelungen"}, {"text": "Nein", "correct": false, "because": "Es ist ein zentrales Gesetz dafür"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BDSG vollständig unabhängig von der Datenschutz-Grundverordnung (DSGVO)?', 2, '[{"text": "Nein", "correct": true, "because": "Das BDSG setzt die DSGVO um und ergänzt sie"}, {"text": "Ja", "correct": false, "because": "Es ist mit der DSGVO verknüpft"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen laut BDSG immer eine Einwilligung für die Verarbeitung personenbezogener Daten einholen?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Rechtsgrundlagen wie Vertragserfüllung sind möglich"}, {"text": "Ja", "correct": false, "because": "Einwilligung ist nicht immer erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Verletzung des BDSG zu Geldbußen führen?', 2, '[{"text": "Ja", "correct": true, "because": "Bußgelder sind bei Verstößen möglich"}, {"text": "Nein", "correct": false, "because": "Sanktionen sind vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Gilt das BDSG ausschließlich für öffentliche Stellen?', 2, '[{"text": "Nein", "correct": true, "because": "Es gilt auch für private Unternehmen"}, {"text": "Ja", "correct": false, "because": "Anwendung ist breiter"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das BDSG primär?', 2, '[{"text": "Schutz personenbezogener Daten", "correct": true, "because": "Datenschutz ist zentral"}, {"text": "Förderung der Datenverarbeitung", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Kostenreduktion", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Behörde überwacht die Einhaltung des BDSG in Deutschland?', 3, '[{"text": "Landesdatenschutzbeauftragte", "correct": true, "because": "Sie sind für die Kontrolle zuständig"}, {"text": "Bundesnetzagentur", "correct": false, "because": "Reguliert Netzwerke"}, {"text": "Finanzamt", "correct": false, "because": "Steuerbehörde"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderung stellt das BDSG an Unternehmen?', 2, '[{"text": "Datenschutzbeauftragten bestellen", "correct": true, "because": "Pflicht bei bestimmten Unternehmen"}, {"text": "Daten immer löschen", "correct": false, "because": "Nicht pauschal"}, {"text": "Keine Daten speichern", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten fallen unter den Schutz des BDSG?', 2, '[{"text": "Personenbezogene Daten", "correct": true, "because": "Daten natürlicher Personen geschützt"}, {"text": "Öffentliche Daten", "correct": false, "because": "Nicht primär geschützt"}, {"text": "Hardware-Daten", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sanktion kann bei Verstößen gegen das BDSG verhängt werden?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Finanzielle Strafen sind üblich"}, {"text": "Warnungen", "correct": false, "because": "Möglich, aber nicht primär"}, {"text": "Systemstilllegung", "correct": false, "because": "Keine Standardstrafe"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche regelt das BDSG?', 4, '[{"text": "Verarbeitung personenbezogener Daten", "correct": true, "because": "Hauptfokus"}, {"text": "Datenschutzbeauftragte", "correct": true, "because": "Regelt Bestellung"}, {"text": "Rechte der Betroffenen", "correct": true, "because": "Schutz der Betroffenen"}, {"text": "Netzwerkgeschwindigkeit", "correct": false, "because": "Kein Datenschutzthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt das BDSG an Unternehmen?', 3, '[{"text": "Datenverarbeitung dokumentieren", "correct": true, "because": "Nachweispflicht"}, {"text": "Einwilligung einholen", "correct": true, "because": "Wenn nötig"}, {"text": "Datensparsamkeit", "correct": true, "because": "Minimierung der Daten"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Gegenteil gilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte haben Betroffene laut BDSG?', 4, '[{"text": "Auskunftsrecht", "correct": true, "because": "Information über gespeicherte Daten"}, {"text": "Löschungsrecht", "correct": true, "because": "Recht auf Vergessen"}, {"text": "Berichtigungsrecht", "correct": true, "because": "Korrektur falscher Daten"}, {"text": "Nutzungsrecht", "correct": false, "because": "Kein Betroffenenrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen bei Verstößen gegen das BDSG?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Finanzielle Sanktionen"}, {"text": "Verwarnungen", "correct": true, "because": "Mildernde Maßnahme"}, {"text": "Verarbeitungsverbot", "correct": true, "because": "Schwere Fälle"}, {"text": "Hardware-Konfiszierung", "correct": false, "because": "Keine Standardstrafe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen laut BDSG?', 3, '[{"text": "Datenschutzbeauftragten ernennen", "correct": true, "because": "Bei bestimmten Kriterien"}, {"text": "Datenverarbeitung melden", "correct": true, "because": "Transparenz schaffen"}, {"text": "Technische Schutzmaßnahmen", "correct": true, "because": "Sicherung der Daten"}, {"text": "Maximale Datenweitergabe", "correct": false, "because": "Gegenteil gilt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das BDSG schützt personenbezogene Daten. b) Es ist unabhängig von der DSGVO.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, Unabhängigkeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unternehmen müssen laut BDSG einen Datenschutzbeauftragten ernennen. b) Eine Einwilligung ist immer nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenschutzbeauftragter ja, Einwilligung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BDSG sieht Bußgelder bei Verstößen vor. b) Es gilt nur für öffentliche Stellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, auch privat betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Betroffene haben ein Auskunftsrecht laut BDSG. b) Das BDSG verbietet jede Datenverarbeitung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auskunft ja, Verarbeitung erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BDSG verlangt technische Schutzmaßnahmen. b) Landesdatenschutzbeauftragte sind nicht involviert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutzmaßnahmen ja, Beauftragte überwachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

